DROP TABLE IF EXISTS `import_replacements`;
/*!40101 SET @saved_cs_client     = @@character_set_client */;
/*!50503 SET character_set_client = utf8mb4 */;
CREATE TABLE `import_replacements` (
  `id` bigint unsigned NOT NULL AUTO_INCREMENT,
  `import_batch_id` bigint unsigned DEFAULT NULL,
  `foreign_product_name` varchar(500) COLLATE utf8mb4_unicode_ci NOT NULL,
  `domestic_product_name` varchar(255) COLLATE utf8mb4_unicode_ci NOT NULL,
  `registry_number` varchar(255) COLLATE utf8mb4_unicode_ci NOT NULL,
  `software_class` text COLLATE utf8mb4_unicode_ci,
  `created_at` timestamp NULL DEFAULT NULL,
  `updated_at` timestamp NULL DEFAULT NULL,
  PRIMARY KEY (`id`),
  UNIQUE KEY `import_replacements_unique` (`foreign_product_name`,`domestic_product_name`),
  KEY `replacement_catalogs_registry_number_index` (`registry_number`),
  KEY `replacement_catalogs_import_batch_id_foreign` (`import_batch_id`),
  CONSTRAINT `replacement_catalogs_import_batch_id_foreign` FOREIGN KEY (`import_batch_id`) REFERENCES `import_batches` (`id`) ON DELETE SET NULL
) ENGINE=InnoDB AUTO_INCREMENT=8192 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;
/*!40101 SET character_set_client = @saved_cs_client */;

