DROP TABLE IF EXISTS `partner_replacements`;
/*!40101 SET @saved_cs_client     = @@character_set_client */;
/*!50503 SET character_set_client = utf8mb4 */;
CREATE TABLE `partner_replacements` (
  `id` bigint unsigned NOT NULL AUTO_INCREMENT,
  `import_batch_id` bigint unsigned DEFAULT NULL,
  `partner_organisation_id` bigint unsigned DEFAULT NULL,
  `partner_organisation_name` text COLLATE utf8mb4_unicode_ci NOT NULL,
  `partner_product_name` varchar(500) COLLATE utf8mb4_unicode_ci NOT NULL,
  `registry_number` varchar(50) COLLATE utf8mb4_unicode_ci NOT NULL,
  `created_at` timestamp NULL DEFAULT NULL,
  `updated_at` timestamp NULL DEFAULT NULL,
  PRIMARY KEY (`id`),
  UNIQUE KEY `partner_replacements_unique` (`partner_organisation_id`,`registry_number`,`partner_product_name`),
  KEY `partner_replacements_registry_number_index` (`registry_number`),
  KEY `partner_replacements_import_batch_id_foreign` (`import_batch_id`),
  KEY `partner_replacements_partner_organisation_id_index` (`partner_organisation_id`),
  CONSTRAINT `partner_replacements_import_batch_id_foreign` FOREIGN KEY (`import_batch_id`) REFERENCES `import_batches` (`id`) ON DELETE SET NULL,
  CONSTRAINT `partner_replacements_partner_organisation_id_foreign` FOREIGN KEY (`partner_organisation_id`) REFERENCES `partner_organisations` (`id`) ON DELETE SET NULL
) ENGINE=InnoDB AUTO_INCREMENT=512 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;
